export default async (ctx, client) => {
  const results = {};

  // 1. The defect: a kind no device executor implements must now be rejected.
  try {
    await client.behaviors.create({
      slug: "tmp-agent-kind-prod-check",
      name: "tmp agent kind prod check",
      prompt: "probe",
      agent_kind: "gemini-cli",
    });
    results.invalid = "ACCEPTED (fix not live)";
  } catch (e) {
    results.invalid = `REJECTED: ${String(e.message ?? e).slice(0, 200)}`;
  }

  // 2. What the old schema told agents to write.
  try {
    await client.behaviors.create({
      slug: "tmp-agent-kind-prod-check-2",
      name: "tmp agent kind prod check 2",
      prompt: "probe",
      agent_kind: "background",
    });
    results.oldDocExample = "ACCEPTED (fix not live)";
  } catch (e) {
    results.oldDocExample = `REJECTED: ${String(e.message ?? e).slice(0, 200)}`;
  }

  return results;
};

export default async (ctx, client) => {
  const out = {};

  // A valid kind must still be accepted — the union must not over-reject.
  const created = await client.behaviors.create({
    slug: "tmp-agent-kind-prod-check-valid",
    name: "tmp agent kind prod check valid",
    prompt: "probe",
    agent_kind: "codex",
  });
  out.validAccepted = { id: created?.id ?? created?.behavior_id ?? null, agent_kind: created?.agent_kind ?? null };

  // Clean up immediately — this is prod.
  const id = created?.id ?? created?.behavior_id;
  if (id) {
    await client.behaviors.delete({ behavior_id: id });
    out.deleted = id;
  }

  // The two rejected writes must have left no rows behind.
  const leftovers = await client.query({
    sql: "SELECT slug FROM watchers WHERE slug LIKE 'tmp-agent-kind-prod-check%'",
  });
  out.leftovers = leftovers;

  return out;
};

export default async (ctx, client) => {
  await client.behaviors.delete({ behavior_ids: [80] });
  const leftovers = await client.query({
    sql: "SELECT id, slug, agent_kind, status FROM watchers WHERE slug LIKE 'tmp-agent-kind-prod-check%'",
  });
  return { leftovers };
};

