/**
 * The Behavior's window cursor: the start of the latest period it has a canvas
 * chain root for, or null if it has none.
 *
 * `canvas_windows` holds one row per root, so this is a bounded per-Behavior
 * lookup, not a history aggregation. Ordered by `window_start` because that is
 * the field being chained; ordering by `window_end` would re-introduce the
 * boundary ambiguity documented on `computePendingWindow`. Zero-content windows
 * count as durable cursor progress too, otherwise empty periods get reprocessed
 * forever.
 *
 * Shared by `computePendingWindow` (which advances it) and the lag reported to
 * the agent (which describes it), so the two can never disagree about where the
 * cursor is.
 */
export async function readWindowCursor(
  sql: DbClient,
  watcherId: number
): Promise<Date | null> {
  const rows = await sql`
    SELECT window_start
    FROM canvas_windows
    WHERE watcher_id = ${watcherId}
    ORDER BY window_start DESC
    LIMIT 1
  `;
  return rows.length > 0 ? new Date(rows[0].window_start as string) : null;
}

/**
 * How far the window cursor trails the clock, in whole granularity periods.
 *
 * Reported to the agent so a stale window is distinguishable from a fresh one
 * from inside a run. Before this existed the dispatch said "your window is
 * June 17" and nothing said today was August 6 — prod Behavior 2 drafted replies
 * to month-dead Hacker News threads for weeks without anything noticing.
 *
 * Deliberately raw facts, not a verdict: no `is_stale` flag and no threshold.
 * Whether fifty missed periods should be skipped or drained depends on what the
 * Behavior is FOR — a drafting Behavior wants to skip, a metrics one wants every
 * period because the gaps are its data — and that judgment lives in the prompt,
 * which the agent is holding and this function will never see.
 *
 * Returns 0 for a Behavior with no windows yet: a fresh Behavior is not behind,
 * and `nextBehaviorWindowStart` already starts it one aligned period back.
 */
export function computeWindowLag(
  cursor: Date | null,
  now: Date,
  granularity: BehaviorTimeGranularity
): { currentPeriodStart: Date; periodsBehind: number } {
  const currentPeriodStart = alignToBehaviorWindowStart(now, granularity);
  if (!cursor) return { currentPeriodStart, periodsBehind: 0 };

  const alignedCursor = alignToBehaviorWindowStart(cursor, granularity);
  // Whole periods between the two aligned instants. Arithmetic rather than a
  // loop so a cursor years adrift costs the same as one a day adrift, and exact
  // because every alignment is UTC — no DST to round over.
  const periodsBehind = wholePeriodsBetween(alignedCursor, currentPeriodStart, granularity);
  return { currentPeriodStart, periodsBehind: Math.max(0, periodsBehind) };
}

const MS_PER_DAY = 86_400_000;

function wholePeriodsBetween(
  from: Date,
  to: Date,
  granularity: BehaviorTimeGranularity
): number {
  switch (granularity) {
    case 'daily':
      return Math.round((to.getTime() - from.getTime()) / MS_PER_DAY);
    case 'weekly':
      return Math.round((to.getTime() - from.getTime()) / (MS_PER_DAY * 7));
    case 'monthly':
      return monthsBetween(from, to);
    case 'quarterly':
      return Math.trunc(monthsBetween(from, to) / 3);
  }
}

