/**
 * Tell the run how stale the window it was handed actually is.
 *
 * Silent in the steady state. A healthy Behavior sits exactly ONE period behind
 * between runs — the cursor is the last completed period and the pending window
 * is the one after it — so `periods_behind <= 1` is normal and says nothing.
 * At 2 or more, the window being analysed is itself already behind the clock.
 *
 * The closing paragraph is the point of the whole thing: the run may choose a
 * different span, and nothing in the dispatch has ever said so.
 */
function formatWindowLag(lag: any): string {
  const periodsBehind = Number(lag?.periods_behind);
  if (!Number.isFinite(periodsBehind) || periodsBehind < 2) return '';

  const unit = String(lag.granularity || 'period');
  // The pending window is cursor + 1, so it trails the current period by one
  // less than the cursor does.
  const windowIsBehind = periodsBehind - 1;

  let md = '## ⏳ This Window Is Behind\n\n';
  md += `The window above is **${windowIsBehind} ${unit} period(s)** behind the current one.\n\n`;
  md += `- Last completed window: \`${lag.last_window_start}\`\n`;
  md += `- Current period starts: \`${lag.current_period_start}\`\n`;
  md += `- The cursor advances ONE period per completed window, so it does not catch up on its own.\n\n`;
  md += 'The window you complete is whatever span you read. To work on a different period, ';
  md += 'call `read_knowledge` again with `since`/`until` and complete the token that returns — ';
  md += 'completing a recent period moves the cursor forward to it, and completing an older one ';
  md += 'never moves it back. Whether the skipped periods are worth analysing, or whether only ';
  md += 'the current one matters, depends on what this Behavior is for.\n\n';
  return md;
}

