/**
 * A Behavior has two cursors and they advance by different rules.
 *
 * The SCHEDULE cursor (`watchers.next_run_at`) is recomputed from `now`, so a
 * missed occurrence is never replayed. The WINDOW cursor
 * (`max(canvas_windows.window_start)`) advances one period per COMPLETED window
 * and is capped at the current period but never jumps to it. Wall-clock moves
 * one period per period, so once a Behavior falls behind it stays behind: the
 * gap is frozen, not closed.
 *
 * Prod Behavior 2 ("HN engagement — draft replies", daily) measured 2026-08-06:
 * newest window `2026-06-17`, written by a run on `2026-07-15`. Drift by window,
 * monotonic — covers 06-06 written 06-11 (5d), 06-14 written 06-27 (13d), 06-15
 * written 07-08 (23d), 06-17 written 07-15 (28d). It was not failing: those late
 * windows carry `content_analyzed = 40`. It read forty real Hacker News stories
 * and drafted real replies to threads a month dead, and reported success.
 *
 * Nothing told it. The dispatch said "your window is June 17" and never that
 * today was August 6 — from inside a run a stale window is indistinguishable
 * from a fresh one. These tests pin the facts now reported, and the alignment of
 * a span the agent picks for itself.
 */

import { describe, expect, test } from "bun:test";
import { alignRequestedWindow, computeWindowLag } from "../../utils/window-utils";

const iso = (d: Date) => d.toISOString();

describe("computeWindowLag", () => {
	// The steady state, and the reason the formatter stays silent below 2: a
	// healthy Behavior always sits exactly one period behind between runs,
	// because the cursor is the last COMPLETED period and the pending window is
	// the one after it.
	test("a healthy Behavior is one period behind, not zero", () => {
		const lag = computeWindowLag(
			new Date("2026-08-05T00:00:00.000Z"),
			new Date("2026-08-06T14:00:00.000Z"),
			"daily",
		);
		expect(lag.periodsBehind).toBe(1);
		expect(iso(lag.currentPeriodStart)).toBe("2026-08-06T00:00:00.000Z");
	});

	test("a just-completed current period reads as zero", () => {
		const lag = computeWindowLag(
			new Date("2026-08-06T00:00:00.000Z"),
			new Date("2026-08-06T14:00:00.000Z"),
			"daily",
		);
		expect(lag.periodsBehind).toBe(0);
	});

	// The prod case, exactly. June 17 -> August 6 is 50 days.
	test("reproduces prod Behavior 2 — 50 daily periods behind", () => {
		const lag = computeWindowLag(
			new Date("2026-06-17T00:00:00.000Z"),
			new Date("2026-08-06T09:30:00.000Z"),
			"daily",
		);
		expect(lag.periodsBehind).toBe(50);
	});

	// A misaligned stored start must not shift the count. Prod holds 14 windows
	// written with an inclusive `23:59:59.999` end and misaligned starts, so the
	// cursor is aligned before measuring rather than trusted as stored.
	test("aligns a misaligned stored cursor before counting", () => {
		const lag = computeWindowLag(
			new Date("2026-06-17T23:59:59.999Z"),
			new Date("2026-08-06T09:30:00.000Z"),
			"daily",
		);
		expect(lag.periodsBehind).toBe(50);
	});

	test("counts whole periods at every granularity", () => {
		expect(
			computeWindowLag(
				new Date("2026-06-01T00:00:00.000Z"),
				new Date("2026-08-06T00:00:00.000Z"),
				"weekly",
			).periodsBehind,
		).toBe(9);
		expect(
			computeWindowLag(
				new Date("2026-02-15T00:00:00.000Z"),
				new Date("2026-08-06T00:00:00.000Z"),
				"monthly",
			).periodsBehind,
		).toBe(6);
		expect(
			computeWindowLag(
				new Date("2025-11-15T00:00:00.000Z"),
				new Date("2026-08-06T00:00:00.000Z"),
				"quarterly",
			).periodsBehind,
		).toBe(3);
	});

	// A Behavior that has never completed a window is not "behind" — it is new,
	// and `nextBehaviorWindowStart` already starts it one aligned period back.
	test("a Behavior with no windows yet is not behind", () => {
		const lag = computeWindowLag(null, new Date("2026-08-06T09:30:00.000Z"), "daily");
		expect(lag.periodsBehind).toBe(0);
		expect(iso(lag.currentPeriodStart)).toBe("2026-08-06T00:00:00.000Z");
	});

	// `nextBehaviorWindowStart` caps at the current period, so a cursor ahead of
	// the clock should be impossible — but prod has held future-dated rows before
	// and a negative lag would render as nonsense.
	test("a cursor ahead of the clock clamps to zero, never negative", () => {
		const lag = computeWindowLag(
			new Date("2026-09-01T00:00:00.000Z"),
			new Date("2026-08-06T09:30:00.000Z"),
			"daily",
		);
		expect(lag.periodsBehind).toBe(0);
	});
});

describe("alignRequestedWindow", () => {
	// The regression. `toEndOfDay` produced `23:59:59.999`, the INCLUSIVE
	// convention that `computePendingWindow` documents as the source of prod's
	// five zero-length windows — and it disagrees with the `>= start AND < end`
	// filter `executeDataSources` applies, so the last millisecond of the range
	// was silently excluded from the events it read.
	test("the end is exclusive, not 23:59:59.999", () => {
		const { windowEnd } = alignRequestedWindow(
			new Date("2026-06-01T00:00:00.000Z"),
			new Date("2026-06-30T00:00:00.000Z"),
			"daily",
		);
		expect(iso(windowEnd)).toBe("2026-07-01T00:00:00.000Z");
		expect(iso(windowEnd)).not.toContain("23:59:59");
	});

	// A multi-period span is the whole point: the unprocessed-ranges formatter
	// tells a daily Behavior to read whole months. Aligning must not collapse
	// that to one day.
	test("preserves a multi-period span", () => {
		const { windowStart, windowEnd } = alignRequestedWindow(
			new Date("2026-06-01T00:00:00.000Z"),
			new Date("2026-06-30T00:00:00.000Z"),
