/**
 * The lag stated in words, or null when there is nothing to say.
 *
 * This exists because reporting the NUMBER was not enough. Measured 2026-08-06
 * against a live run: a Behavior seeded fifty periods behind, handed
 * `periods_behind: 50`, analysed the stale window anyway and advanced the cursor
 * by exactly one period — the prod pathology reproduced WITH the lag field in
 * place. Behavior runs reach knowledge through `run_sdk`, which returns JSON, so
 * all the model ever saw was four numbers inside a thirteen-key object. The
 * prose lived in the markdown formatter, on a path Behavior runs never take.
 *
 * So the guidance travels WITH the data, on every surface. A number tells a run
 * that it is behind; only this tells it that the cursor will not recover on its
 * own and that it is allowed to ask for a different span.
 *
 * Silent below two periods: a healthy Behavior always sits exactly one period
 * behind between runs (the cursor is the last completed period, the pending
 * window is the next), so speaking up at one would fire on every healthy run and
 * train the model to skip it.
 */
export function describeWindowLag(lag: {
  lastWindowStart: Date | null;
  currentPeriodStart: Date;
  periodsBehind: number;
  granularity: BehaviorTimeGranularity;
}): string | null {
  if (lag.periodsBehind < 2 || !lag.lastWindowStart) return null;
  return (
    `This Behavior is ${lag.periodsBehind} ${lag.granularity} period(s) behind. Its last ` +
    `completed window starts ${lag.lastWindowStart.toISOString()}, but the current period ` +
    `starts ${lag.currentPeriodStart.toISOString()}. The cursor advances only ONE period per ` +
    'completed window, so it will not catch up on its own. The window you complete is whatever ' +
    'span you read: call read_knowledge again with `since`/`until` and complete the token it ' +
    'returns. Completing a recent period moves the cursor forward to it; completing an older ' +
    'one never moves it back. Decide from this Behavior\'s purpose whether the skipped periods ' +
    'are worth analysing or whether only the current period matters.'
  );
}

