24	import { describe, expect, test } from "bun:test";
25	import { formatToolResult } from "../../formatting/markdown-formatter";
26	import {
27		alignRequestedWindow,
28		computeWindowLag,
29		describeWindowLag,
30		parseBehaviorWindowDate,
31	} from "../../utils/window-utils";
32	
33	const iso = (d: Date) => d.toISOString();
34	
35	/**
36	 * What `parseDateAlias` hands `alignRequestedWindow` in production: LOCAL
37	 * midnight (or local time) of the written calendar day. Constructing fixtures
38	 * as UTC instants instead would make every assertion below depend on the test
39	 * machine's timezone — `asUtcCalendarDay` reads local date parts, so a UTC
40	 * midnight local-reads as the PREVIOUS day anywhere west of UTC.
41	 */
42	// `alignRequestedWindow` is pure UTC — every boundary in window-utils is
43	// `setUTC*`, and the local zone is normalized away earlier by
44	// `parseBehaviorWindowDate`. So its fixtures are UTC instants, and these
45	// assertions hold identically under every TZ.
46	const utcDate = (y: number, mo: number, d: number, h = 0, mi = 0, s = 0) =>
47		new Date(Date.UTC(y, mo - 1, d, h, mi, s));
48	
49	describe("computeWindowLag", () => {
50		// The steady state, and the reason the formatter stays silent below 2: a
51		// healthy Behavior always sits exactly one period behind between runs,
52		// because the cursor is the last COMPLETED period and the pending window is
53		// the one after it.
54		test("a healthy Behavior is one period behind, not zero", () => {
55			const lag = computeWindowLag(
56				new Date("2026-08-05T00:00:00.000Z"),
57				new Date("2026-08-06T14:00:00.000Z"),
58				"daily",
59			);
60			expect(lag.periodsBehind).toBe(1);
61			expect(iso(lag.currentPeriodStart)).toBe("2026-08-06T00:00:00.000Z");
62		});
63	
64		test("a just-completed current period reads as zero", () => {
65			const lag = computeWindowLag(
66				new Date("2026-08-06T00:00:00.000Z"),
