212	/**
213	 * The JSON field is the contract; this markdown is what an LLM run actually
214	 * reads. A field the model never sees fixes nothing, so the rendered surface is
215	 * pinned here too — including the sentence that tells the run it may choose a
216	 * different span, which is the entire point of the change.
217	 */
218	describe("read_knowledge markdown — window lag", () => {
219		// Built exactly as behavior-mode builds it, guidance included — the formatter
220		// renders the SAME string the JSON payload carries, so a fixture without it
