222		const lagFor = (periodsBehind: number) => ({
223			last_window_start: "2026-06-17T00:00:00.000Z",
224			current_period_start: "2026-08-06T00:00:00.000Z",
225			periods_behind: periodsBehind,
226			granularity: "daily",
227			...(describeWindowLag({
