302	/**
303	 * `get_behavior.pending_analysis.next_action` hands an MCP client a literal
304	 * `read_knowledge` call for the window it just previewed. That suggestion has to
305	 * round-trip: feeding its `since`/`until` back through `alignRequestedWindow`
306	 * must reproduce the previewed window exactly, or the server is telling clients
307	 * to write windows the dispatcher would never emit.
308	 *
309	 * It did not. `until` was `next_window.end` — the EXCLUSIVE boundary — so a
310	 * one-day window was advertised as a two-day range.
311	 */
312	describe("next_action round-trips to the previewed window", () => {
313		// Mirrors the construction in get_behavior.ts: `until` is the last instant
314		// inside the window, rendered as a date.
315		const suggest = (start: string, end: string) => ({
316			since: start.split("T")[0],
317			until: new Date(new Date(end).getTime() - 1).toISOString().split("T")[0],
318		});
319	
320		// A "YYYY-MM-DD" param as local midnight — what parseDateAlias produces for
321		// it on a server whose ISO branch resolves the written day correctly.
322		const localDay = (s: string) => {
323			const [y, mo, d] = s.split("-").map(Number);
324			return utcDate(y, mo, d);
325		};
326	
327		test.each([
328			["daily", "2026-06-18T00:00:00.000Z", "2026-06-19T00:00:00.000Z"],
329			["weekly", "2026-06-15T00:00:00.000Z", "2026-06-22T00:00:00.000Z"],
330			["monthly", "2026-06-01T00:00:00.000Z", "2026-07-01T00:00:00.000Z"],
331			["quarterly", "2026-04-01T00:00:00.000Z", "2026-07-01T00:00:00.000Z"],
332		] as const)("%s", (granularity, start, end) => {
333			const { since, until } = suggest(start, end);
334			const round = alignRequestedWindow(localDay(since), localDay(until), granularity);
335			expect(iso(round.windowStart)).toBe(start);
336			expect(iso(round.windowEnd)).toBe(end);
337		});
338	
339		// The bug, pinned directly: the exclusive end as `until` widens by a period.
340		test("passing the exclusive end as until widens the window", () => {
341			const wrong = alignRequestedWindow(
342				localDay("2026-06-18"),
343				localDay("2026-06-19"),
344				"daily",
345			);
346			expect(iso(wrong.windowEnd)).toBe("2026-06-20T00:00:00.000Z");
347		});
348	});
349	
350	/**
351	 * The timezone trap, pinned. `parseDateAlias` returns midnight in the SERVER's
352	 * local zone; window boundaries are UTC. East of UTC that local midnight is
353	 * still the PREVIOUS UTC day, so aligning it with `setUTCHours` wrote the
354	 * 2026-08-05 window for "give me 2026-08-06" — and `get_behavior.next_action`
355	 * hands clients exactly such a date string, so the server's own suggestion did
356	 * not round-trip on an east-of-UTC deployment. (West of UTC the day is lost
357	 * inside parseDateAlias's ISO branch before alignment ever runs — that trap is
358	 * shared with every `since`/`until` consumer and out of this branch's reach.)
359	 *
360	 * Only the e2e caught this; every unit assertion above passes in UTC either way.
361	 */
362	describe("parseBehaviorWindowDate is timezone-stable", () => {
363		// `bun test` runs with TZ=UTC, where a local date and a UTC date are the same
364		// instant — so this suite is only meaningful under an explicit TZ. Run it as:
365		//   TZ=America/New_York bun test src/__tests__/unit/behavior-window-lag.test.ts
366		//   TZ=Europe/Istanbul  bun test ...
367		// Both must be green. The previous version of this block fed `new Date(y,m,d)`
368		// into the aligner and asserted a UTC day; under TZ=UTC that is a tautology,
369		// which is exactly how the production bug survived every unit test.
370		test("a bare YYYY-MM-DD is that UTC day, in any zone", () => {
371			expect(iso(parseBehaviorWindowDate("2026-08-06"))).toBe("2026-08-06T00:00:00.000Z");
372			expect(iso(parseBehaviorWindowDate("2026-01-01"))).toBe("2026-01-01T00:00:00.000Z");
373			// Whitespace is tolerated the same way parseDateAlias tolerates it.
374			expect(iso(parseBehaviorWindowDate("  2026-08-06 "))).toBe("2026-08-06T00:00:00.000Z");
375		});
376	
377		test("the window it produces is that day, in any zone", () => {
378			const day = parseBehaviorWindowDate("2026-08-06");
379			const { windowStart, windowEnd } = alignRequestedWindow(day, day, "daily");
380			expect(iso(windowStart)).toBe("2026-08-06T00:00:00.000Z");
381			expect(iso(windowEnd)).toBe("2026-08-07T00:00:00.000Z");
382		});
383	
384		// `get_behavior.next_action` emits `YYYY-MM-DD` strings, so the server's own
385		// suggestion has to survive this path on a non-UTC deployment.
386		test("next_action's date strings round-trip to the previewed window", () => {
387			const start = "2026-06-18T00:00:00.000Z";
388			const end = "2026-06-19T00:00:00.000Z";
389			const since = start.split("T")[0];
390			const until = new Date(new Date(end).getTime() - 1).toISOString().split("T")[0];
391			const round = alignRequestedWindow(
392				parseBehaviorWindowDate(since),
393				parseBehaviorWindowDate(until),
394				"daily",
395			);
396			expect(iso(round.windowStart)).toBe(start);
397			expect(iso(round.windowEnd)).toBe(end);
398		});
399	
400		// Aliases are relative to the server clock by definition; what must hold is
401		// that the day they land on is expressed as UTC midnight, never a local one.
402		test("an alias resolves to a UTC midnight", () => {
403			const today = parseBehaviorWindowDate("today");
404			expect(today.getUTCHours()).toBe(0);
405			expect(today.getUTCMinutes()).toBe(0);
406			expect(today.getUTCSeconds()).toBe(0);
407			expect(today.getUTCMilliseconds()).toBe(0);
408		});
409	});
