describe("read_knowledge markdown — window lag", () => {
	// Built exactly as behavior-mode builds it, guidance included — the formatter
	// renders the SAME string the JSON payload carries, so a fixture without it
	// would test a shape production never emits.
	const lagFor = (periodsBehind: number) => ({
		last_window_start: "2026-06-17T00:00:00.000Z",
		current_period_start: "2026-08-06T00:00:00.000Z",
		periods_behind: periodsBehind,
		granularity: "daily",
		...(describeWindowLag({
			lastWindowStart: new Date("2026-06-17T00:00:00.000Z"),
			currentPeriodStart: new Date("2026-08-06T00:00:00.000Z"),
			periodsBehind,
			granularity: "daily",
		})
			? {
					guidance: describeWindowLag({
						lastWindowStart: new Date("2026-06-17T00:00:00.000Z"),
						currentPeriodStart: new Date("2026-08-06T00:00:00.000Z"),
						periodsBehind,
						granularity: "daily",
					}) as string,
				}
			: {}),
	});

	const render = (periodsBehind: number) =>
		formatToolResult("read_knowledge", {
			total: 40,
			content: [],
			page: { limit: 100, offset: 0, has_more: false },
			window_token: "tok",
			window_start: "2026-06-18T00:00:00.000Z",
			window_end: "2026-06-19T00:00:00.000Z",
			window_lag: lagFor(periodsBehind),
		});

	// Silent in the steady state — a Behavior always sits one period behind
	// between runs, so warning at 1 would fire on every healthy run and train
	// the model to ignore it.
	test("says nothing when the Behavior is current", () => {
		expect(render(0)).not.toContain("Behind");
		expect(render(1)).not.toContain("Behind");
	});

	test("reports the lag once the cursor is stale", () => {
		const md = render(50);
		expect(md).toContain("This Behavior Is Behind");
		// The count is about the CURSOR, never "the window above" — the window
		// may be an agent-chosen `since`/`until` range, possibly the current
		// period read on this notice's own advice, so a claim about its
		// staleness would be wrong exactly when the run acts on the notice.
		expect(md).toContain("50 daily period(s)");
		expect(md).toContain("2026-06-17T00:00:00.000Z");
		expect(md).toContain("2026-08-06T00:00:00.000Z");
	});

	test("tells the run it can choose a different span", () => {
		const md = render(50);
		expect(md).toContain("since");
		expect(md).toContain("until");
		expect(md).toContain("read_knowledge");
	});

	// `watcher` is internal DB vocabulary and must never reach an agent-facing
	// surface — `make pre-pr` fails the build on it.
	test("uses Behavior vocabulary, never watcher", () => {
		expect(render(50).toLowerCase()).not.toContain("watcher");
	});

	test("a Behavior with no lag field renders unchanged", () => {
		const md = formatToolResult("read_knowledge", {
			total: 0,
			content: [],
			page: { limit: 100, offset: 0, has_more: false },
			window_token: "tok",
			window_start: "2026-08-06T00:00:00.000Z",
			window_end: "2026-08-07T00:00:00.000Z",
		});
		expect(md).toContain("Behavior Window");
		expect(md).not.toContain("This Behavior Is Behind");
	});
});

